const me = $('Threads Profilini Doğrula').first()?.json || {};
const threadsUserId = String(me.id || '').trim();
if (!threadsUserId) {
  throw new Error('Threads profili doğrulanamadı. Tokenı kontrol edin.');
}

const recentRaw = $('Son Gönderileri Çek').first()?.json || {};
const recentPosts = Array.isArray(recentRaw.data) ? recentRaw.data : [];

const ghRaw = $input.first()?.json || {};
let posts = [];
try {
  const fs = require('fs');
  const LOCAL_QUEUE = 'C:\\Users\\idoca\\Socialora\\automation\\threads\\content-queue.json';
  if (fs.existsSync(LOCAL_QUEUE)) {
    const localParsed = JSON.parse(fs.readFileSync(LOCAL_QUEUE, 'utf8'));
    if (Array.isArray(localParsed.posts) && localParsed.posts.length > 0) posts = localParsed.posts;
  }
} catch {}
if (posts.length === 0) {
  try {
    const parsed = typeof ghRaw === 'string' ? JSON.parse(ghRaw) : (typeof ghRaw.data === 'string' ? JSON.parse(ghRaw.data) : ghRaw);
    if (Array.isArray(parsed.posts)) posts = parsed.posts;
  } catch {}
}

if (posts.length === 0) return [];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const readDiskPlatform = () => {
  try {
    const fs = require('fs');
    if (!fs.existsSync(GROWTH_PATH)) return {};
    const full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8'));
    return (full && typeof full.threads === 'object' && full.threads) ? full.threads : {};
  } catch { return {}; }
};
const sd = $getWorkflowStaticData('global');
const diskTh = readDiskPlatform();
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (Array.isArray(diskTh.sentIds)) sd.sentIds = [...new Set([...sd.sentIds, ...diskTh.sentIds])];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (Array.isArray(diskTh.sentHistory)) {
  const seenH = new Set(sd.sentHistory.map((h) => h.postId + ':' + h.sentAt));
  for (const h of diskTh.sentHistory) { const k = h.postId + ':' + h.sentAt; if (!seenH.has(k)) { seenH.add(k); sd.sentHistory.push(h); } }
  sd.sentHistory = sd.sentHistory.slice(-80);
}
sd.lastPublishedAt = Math.max(Number(sd.lastPublishedAt || 0), Number(diskTh.lastPublishedAt || 0));

const nowSec = Math.floor(Date.now() / 1000);
const trtNow = new Date((nowSec + 3 * 3600) * 1000);
const todayTrt = trtNow.toISOString().slice(0, 10);
const hourTrt = trtNow.getUTCHours();

let isManual = false;
try { if (typeof $execution !== 'undefined' && $execution.mode === 'manual') isManual = true; } catch {}
try { if ($('Manuel Tetikle').isExecuted) isManual = true; } catch {}

let latestLiveTs = 0;
let liveTodayCount = 0;
const liveTexts = [];
for (const m of recentPosts) {
  if (m.text) liveTexts.push(String(m.text).toLowerCase().trim());
  if (m.timestamp) {
    const ts = Math.floor(Date.parse(m.timestamp) / 1000);
    if (Number.isFinite(ts) && ts > 0) {
      if (ts > latestLiveTs) latestLiveTs = ts;
      const dStr = new Date((ts + 3 * 3600) * 1000).toISOString().slice(0, 10);
      if (dStr === todayTrt) liveTodayCount += 1;
    }
  }
}

const sdCountToday = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
const diskCountToday = diskTh.dayTrt === todayTrt ? Number(diskTh.countToday || 0) : 0;
sd.dayTrt = todayTrt;
sd.countToday = Math.max(liveTodayCount, sdCountToday, diskCountToday);
if (!isManual) {
  if (hourTrt < 14 || hourTrt > 23) return [];
  const effectiveLast = Math.max(sd.lastPublishedAt, latestLiveTs);
  if (sd.countToday >= 4) return [];
  if (effectiveLast && (nowSec - effectiveLast < 2.5 * 3600)) return [];
}

const sentSet = new Set(sd.sentIds);
const candidate = posts.find((p) => {
  if (!p || !p.id || !p.text) return false;
  if (sentSet.has(p.id)) return false;
  const firstLine = String(p.text).split('\n')[0].toLowerCase().trim();
  if (firstLine.length >= 18 && liveTexts.some((t) => t.includes(firstLine))) return false;
  return true;
});

if (!candidate) return [];

const cleanText = (s) => String(s || '')
  .replace(/\s*[\u2014\u2013]\s*/g, ', ')
  .replace(/[\u2022]/g, '-')
  .trim();

const ALLOWED_TAGS = new Set([
  'Instagram Growth',
  'Creator Tips',
  'Video Editing',
  'Content Strategy',
  'UGC Creators',
  'Social Media Design',
  'YouTube Tips',
  'TikTok Tips'
]);

const body = {
  media_type: candidate.image_url ? 'IMAGE' : 'TEXT',
  text: cleanText(candidate.text).slice(0, 500)
};
if (candidate.image_url) body.image_url = candidate.image_url;
if (candidate.topic_tag) {
  const rawTag = String(candidate.topic_tag).replace(/[.&]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 50);
  if (ALLOWED_TAGS.has(rawTag)) {
    body.topic_tag = rawTag;
  } else if (rawTag) {
    body.topic_tag = 'Creator Tips';
  }
}

const replyText = candidate.reply_text ? cleanText(candidate.reply_text).slice(0, 500) : '';
const hasUrlInReply = /https?:\/\//i.test(replyText);
const isSecondWave = Boolean(replyText && !hasUrlInReply && (candidate.pillar === 'framework' || candidate.pillar === 'hook_truth'));
let h = 2166136261;
const seed = String(candidate.id) + ':' + todayTrt;
for (let i = 0; i < seed.length; i++) h = Math.imul(h ^ seed.charCodeAt(i), 16777619) >>> 0;
const replyDelaySec = isSecondWave ? (240 + (h % 121)) : 4;

return [{
  json: {
    threadsUserId,
    username: String(me.username || 'socialora1'),
    postId: candidate.id,
    pillar: candidate.pillar || '',
    payload: body,
    replyText,
    replyDelaySec,
    isSecondWave,
    nowSec
  }
}];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const syncDiskPlatform = (patch, incrementCount) => {
  const fs = require('fs');
  const path = require('path');
  let full = {};
  try {
    if (fs.existsSync(GROWTH_PATH)) full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {};
  } catch { full = {}; }
  const prev = (full && typeof full.threads === 'object' && full.threads) ? full.threads : {};
  const mergedIds = [...new Set([...(Array.isArray(prev.sentIds) ? prev.sentIds : []), ...(Array.isArray(patch.sentIds) ? patch.sentIds : [])])];
  const prevDiskCount = prev.dayTrt === patch.dayTrt ? Number(prev.countToday || 0) : 0;
  const baseCount = Math.max(prevDiskCount, Number(patch.prevSdCount || 0));
  const nextCount = incrementCount ? baseCount + 1 : Math.max(baseCount, Number(patch.countToday || 0));
  const nextObj = {
    ...prev,
    ...patch,
    sentIds: mergedIds.slice(-300),
    lastPublishedAt: Math.max(Number(prev.lastPublishedAt || 0), Number(patch.lastPublishedAt || 0)),
    countToday: nextCount,
  };
  delete nextObj.prevSdCount;
  if (Array.isArray(patch.sentHistory)) {
    const prevH = Array.isArray(prev.sentHistory) ? prev.sentHistory : [];
    const seenH = new Set(prevH.map((h) => h.postId + ':' + h.sentAt));
    const combined = [...prevH];
    for (const h of patch.sentHistory) {
      const k = h.postId + ':' + h.sentAt;
      if (!seenH.has(k)) { seenH.add(k); combined.push(h); }
    }
    nextObj.sentHistory = combined.slice(-80);
  }
  full.threads = nextObj;
  fs.mkdirSync(path.dirname(GROWTH_PATH), { recursive: true });
  const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
  fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
  fs.renameSync(tmp, GROWTH_PATH);
  return nextObj;
};
const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
const mainPub = $('Threads Gönderisini Yayınla').first()?.json || {};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (!sd.sentIds.includes(picked.postId)) sd.sentIds.push(picked.postId);
const nowSec = Math.floor(Date.now() / 1000);
const todayTrt = new Date((nowSec + 3 * 3600) * 1000).toISOString().slice(0, 10);
const prevSdCount = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
sd.lastPublishedAt = nowSec;
sd.sentHistory.push({
  postId: picked.postId,
  threadsPostId: String(mainPub.id || ''),
  sentAt: sd.lastPublishedAt
});
sd.sentHistory = sd.sentHistory.slice(-80);
const synced = syncDiskPlatform({
  sentIds: sd.sentIds,
  lastPublishedAt: sd.lastPublishedAt,
  dayTrt: todayTrt,
  prevSdCount,
  sentHistory: sd.sentHistory
}, true);
sd.sentIds = synced.sentIds;
sd.lastPublishedAt = synced.lastPublishedAt;
sd.dayTrt = synced.dayTrt;
sd.countToday = synced.countToday;
return [{ json: { ok: true, postId: picked.postId, threadsPostId: mainPub.id || null, username: picked.username, countToday: sd.countToday } }];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const readDiskPlatform = () => {
  try {
    const fs = require('fs');
    if (!fs.existsSync(GROWTH_PATH)) return {};
    const full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8'));
    return (full && typeof full.threads === 'object' && full.threads) ? full.threads : {};
  } catch { return {}; }
};
const nowSec = Math.floor(Date.now() / 1000);
const trt = new Date((nowSec + 3 * 3600) * 1000);
const today = trt.toISOString().slice(0, 10);
const h = trt.getUTCHours();
const m = trt.getUTCMinutes();
const hash = (s) => { let v = 2166136261; for (let i = 0; i < s.length; i++) v = Math.imul(v ^ s.charCodeAt(i), 16777619) >>> 0; return v; };
const sd = $getWorkflowStaticData('global');
const diskTh = readDiskPlatform();
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (Array.isArray(diskTh.sentIds)) sd.sentIds = [...new Set([...sd.sentIds, ...diskTh.sentIds])];
sd.lastPublishedAt = Math.max(Number(sd.lastPublishedAt || 0), Number(diskTh.lastPublishedAt || 0));
const sdCount = sd.dayTrt === today ? Number(sd.countToday || 0) : 0;
const diskCount = diskTh.dayTrt === today ? Number(diskTh.countToday || 0) : 0;
sd.dayTrt = today;
sd.countToday = Math.max(sdCount, diskCount);
if (sd.countToday >= 4) return [];
const lastPub = Number(sd.lastPublishedAt || 0);
if (lastPub && (nowSec - lastPub < 2.5 * 3600)) return [];
const slots = [
  [14, 2],
  [17, 2],
  [20, 2],
  [23, 1],
];
let readySlot = null;
for (let i = 0; i < slots.length; i++) {
  const hv = hash(today + ':th_' + i);
  const targetH = slots[i][0] + (hv % slots[i][1]);
  const targetM = 4 + ((hv >>> 4) % 49);
  const maxH = slots[i][0] + slots[i][1];
  if ((h > targetH || (h === targetH && m >= targetM)) && h <= maxH) {
    readySlot = i + 1;
  }
}
if (!readySlot) return [];
return [{ json: { ok: true, slot: readySlot, nowSec } }];
